import{_ as a,o as t,c as r,aj as i}from"./chunks/framework.BZLKZzpg.js";const m=JSON.parse('{"title":"Unitat 5. Frameworks. Laravel","description":"","frontmatter":{},"headers":[],"relativePath":"contenidos/5-frameworks-laravel/index.md","filePath":"contenidos/5-frameworks-laravel/index.md"}'),s={name:"contenidos/5-frameworks-laravel/index.md"};function n(o,e,l,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="unitat-5-frameworks-laravel" tabindex="-1">Unitat 5. Frameworks. Laravel <a class="header-anchor" href="#unitat-5-frameworks-laravel" aria-label="Permalink to &quot;Unitat 5. Frameworks. Laravel&quot;">​</a></h1><p>En esta unitat desenvoluparàs una aplicació web completa amb <strong>Laravel</strong>, un framework de PHP. Treballaràs amb un únic projecte durant tota la unitat: una aplicació per a crear <strong>etiquetes de productes alimentaris</strong>.</p><ul><li><strong>Part pública</strong>: les etiquetes publicades es mostren com els articles d&#39;un blog, amb imatge, descripció, data, autor i categoria.</li><li><strong>Part privada</strong>: les persones registrades creen les seues etiquetes (producte, varietat, pes net, calibre, origen, lot, envasador, codis i data d&#39;envasat) i les descarreguen en <strong>PDF</strong>.</li></ul><p>L&#39;entorn de treball és <strong>Docker amb Laravel Sail</strong>. Durant la unitat anirem incorporant la intel·ligència artificial: primer com a tutor, després com a assistent en tasques concretes i, al final, amb agents.</p><h2 id="resultats-d-aprenentatge-i-criteris-d-avaluacio" tabindex="-1">Resultats d&#39;aprenentatge i criteris d&#39;avaluació <a class="header-anchor" href="#resultats-d-aprenentatge-i-criteris-d-avaluacio" aria-label="Permalink to &quot;Resultats d&#39;aprenentatge i criteris d&#39;avaluació&quot;">​</a></h2><details class="details custom-block"><summary>📋 Resultats d&#39;aprenentatge i criteris d&#39;avaluació</summary><p><strong>RA 5. Desenvolupa aplicacions Web identificant i aplicant mecanismes per a separar el codi de presentació de la lògica de negoci.</strong></p><ul><li><strong>Criteris d&#39;avaluació:</strong></li><li><strong>a)</strong> S&#39;han identificat els avantatges de separar la lògica de negoci dels aspectes de presentació de l&#39;aplicació.</li><li><strong>b)</strong> S&#39;han analitzat tecnologies i mecanismes que permeten realitzar aquesta separació i les seues característiques principals.</li><li><strong>c)</strong> S&#39;han utilitzat objectes i controls en el servidor per a generar l&#39;aspecte visual de l&#39;aplicació web en el client.</li><li><strong>d)</strong> S&#39;han utilitzat formularis generats de manera dinàmica per a respondre als esdeveniments de l&#39;aplicació Web.</li><li><strong>e)</strong> S&#39;han identificat i aplicat els paràmetres relatius a la configuració de l&#39;aplicació Web.</li><li><strong>f)</strong> S&#39;han escrit aplicacions Web amb manteniment d&#39;estat i separació de la lògica de negoci.</li><li><strong>g)</strong> S&#39;han aplicat els principis de la programació orientada a objectes.</li><li><strong>h)</strong> S&#39;ha provat i documentat el codi.</li></ul><p><strong>RA8. Genera pàgines web dinàmiques analitzant i utilitzant tecnologies i frameworks del servidor web que afigen codi al llenguatge de marques.</strong></p><ul><li><strong>Criteris d&#39;avaluació:</strong></li><li><strong>a)</strong> S&#39;han identificat les diferències entre l&#39;execució de codi en el servidor i en el client web.</li><li><strong>b)</strong> S&#39;han reconegut els avantatges d&#39;unir totes dues tecnologies en el procés de desenvolupament de programes.</li><li><strong>c)</strong> S&#39;han identificat les tecnologies i frameworks relacionades amb la generació per part del servidor de pàgines web amb guions embeguts.</li><li><strong>d)</strong> S&#39;han utilitzat aquestes tecnologies i frameworks per a generar pàgines web que incloguen interacció amb l&#39;usuari.</li><li><strong>e)</strong> S&#39;han utilitzat aquestes tecnologies i frameworks, per a generar pàgines web que incloguen verificació de formularis.</li><li><strong>f)</strong> S&#39;han utilitzat aquestes tecnologies i frameworks per a generar pàgines web que incloguen modificació dinàmica del seu contingut i la seua estructura.</li><li><strong>g)</strong> S&#39;han aplicat aquestes tecnologies i frameworks en la programació d&#39;aplicacions web.</li></ul></details><h2 id="blocs-de-la-unitat" tabindex="-1">Blocs de la unitat <a class="header-anchor" href="#blocs-de-la-unitat" aria-label="Permalink to &quot;Blocs de la unitat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bloc</th><th>Què treballaràs</th><th>Hores</th></tr></thead><tbody><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-1-introduccio-i-sail.html">Bloc 1. Introducció i Laravel Sail</a></td><td>L&#39;entorn de treball amb Docker i l&#39;estructura d&#39;un projecte Laravel</td><td>3</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-2-rutes-i-vistes.html">Bloc 2. Rutes i vistes</a></td><td>Rutes amb nom, vistes Blade i components</td><td>4</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-3-controladors.html">Bloc 3. Controladors</a></td><td>Controladors, controladors d&#39;una sola acció i controladors de recurs</td><td>3</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-4-models-de-dades.html">Bloc 4. Models de dades</a></td><td>Base de dades, migracions, Eloquent, relacions, seeders i factories</td><td>7</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-5-formularis.html">Bloc 5. Formularis</a></td><td>Formularis, validació i Form Requests</td><td>4</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-6-autenticacio.html">Bloc 6. Autenticació</a></td><td>Registre, inici de sessió i autorització amb sessions</td><td>3</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-7-arxius-correus-sessions-i-cookies.html">Bloc 7. Arxius, correus, sessions i cookies</a></td><td>Pujada d&#39;arxius, PDF, enviament de correus, sessions i cookies</td><td>3</td></tr><tr><td><a href="/DWES/contenidos/5-frameworks-laravel/5-8-ia-agents-i-projecte-final.html">Bloc 8. IA, agents i projecte final</a></td><td>Treball amb IA i agents, i projecte final</td><td>11</td></tr></tbody></table><h2 id="temporalitzacio" tabindex="-1">Temporalització <a class="header-anchor" href="#temporalitzacio" aria-label="Permalink to &quot;Temporalització&quot;">​</a></h2><p>La unitat té una durada total de <strong>38 hores</strong>.</p>',10)])])}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
